export function validateJobBody(body: unknown): { value: JobInput } | { fields: FieldError[] } {
  if (!isPlainObject(body)) return { fields: [{ field: 'body', message: 'body must be a JSON object' }] };

  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  const { input, steps = 5, failAttempts = 0 } = body;

  let validInput: string | undefined;
  if (input === undefined) {
    fields.push({ field: 'input', message: 'input is required' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'input must be a string' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
  } else if (input.trim().length === 0) {
    fields.push({ field: 'input', message: 'input must not be blank' });
  } else {
    validInput = input;
  }

  if (!integerIn(steps, 1, 20)) fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20' });
  if (!integerIn(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5' });

  if (fields.length > 0 || validInput === undefined) return { fields };
  return { value: { input: validInput, steps: steps as number, failAttempts: failAttempts as number } };
}

/** Validates the Idempotency-Key header. Returns a field error, or undefined when valid or absent. */
export function validateIdempotencyKey(key: string | undefined): FieldError | undefined {
  if (key === undefined || IDEMPOTENCY_KEY_RE.test(key)) return undefined;
  return { field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$' };
