  send(res, status, { error: fields === undefined ? { code, message } : { code, message, fields } });
}

function sendInvalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

/** Reads the request body as text. Resolves to null when the body is larger than MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function isJsonContentType(header: string | undefined): boolean {
  if (header === undefined) return false;
  return header.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

function nowIso(): string {
  return new Date().toISOString();
}

/** Inserts a job. Runs inside a transaction when an idempotency key is given, so a key never yields two jobs. */
function createJob(params: JobInput, key: string | undefined): { created: boolean; row: JobRow; conflict: boolean } {
  const fingerprint = key === undefined ? null : JSON.stringify([params.input, params.steps, params.failAttempts]);
  const insert = (): JobRow => {
    const id = randomUUID();
    const now = nowIso();
    insertJob.run(id, params.input, params.steps, params.failAttempts, key ?? null, fingerprint, Date.now(), now, now);
    return selectById.get(id) as JobRow;
  };
  if (key === undefined) return { created: true, row: insert(), conflict: false };

  db.exec('BEGIN IMMEDIATE');
  try {
    const existing = selectByKey.get(key) as (JobRow & { fingerprint: string | null }) | undefined;
    let result: { created: boolean; row: JobRow; conflict: boolean };
    if (existing) {
      result = { created: false, row: existing, conflict: existing.fingerprint !== fingerprint };
    } else {
      result = { created: true, row: insert(), conflict: false };
    }
    db.exec('COMMIT');
    return result;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

async function handlePostJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const keyHeader = req.headers['idempotency-key'];
  const key = typeof keyHeader === 'string' ? keyHeader : undefined;
  const fields: FieldError[] = [];
  const keyError = validateIdempotencyKey(key);
  if (keyError) fields.push(keyError);

  const raw = await readBody(req);
  if (raw === null) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
    return sendInvalid(res, fields);
  }
  if (!isJsonContentType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    return sendInvalid(res, fields);
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    fields.push({ field: 'body', message: 'body is not valid JSON' });
    return sendInvalid(res, fields);
  }

  const validated = validateJobBody(parsed);
  if (!('value' in validated)) {
    fields.push(...validated.fields);
    return sendInvalid(res, fields);
  }
  if (fields.length > 0) return sendInvalid(res, fields);

  const result = createJob(validated.value, key);
  if (result.conflict) {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, result.created ? 201 : 200, toJob(result.row));
}

function handleGetJob(res: ServerResponse, id: string): void {
  const row = selectById.get(id) as JobRow | undefined;
  if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
  send(res, 200, toJob(row));
}

function handleList(res: ServerResponse): void {
  const rows = selectAll.all() as unknown as JobRow[];
  const jobs: Job[] = rows.map(toJob);
  send(res, 200, { jobs });
}

function handleHealth(res: ServerResponse): void {
  const beat = selectHeartbeat.get('worker') as { at: number } | undefined;
  const up = beat !== undefined && Date.now() - Number(beat.at) <= WORKER_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Use ${allowed.join(', ')}.`);
  res.setHeader('allow', allowed.join(', '));
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') return method === 'GET' ? handleHealth(res) : methodNotAllowed(res, ['GET']);
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return handleList(res);
    if (method === 'POST') return handlePostJob(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) return method === 'GET' ? handleGetJob(res, match[1]!) : methodNotAllowed(res, ['GET']);
  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
